/**
 * Icons exported from the Figma file (Hicon / Linear set, 1.5px stroke, plus
 * the pharmacy side-nav icons and the sun/moon toggle icons). Only icons the
 * shared components and screens use are included. Colours are stripped so
 * every icon takes `currentColor` / the `color` prop.
 *
 * `stroke` paths are drawn with a 1.5px line at the icon's rendered size,
 * matching the chevrons. `fill` paths are Figma outlines of 1.5px strokes (or
 * small dots) and are filled.
 *
 * Use chevrons, not arrows, for back and forward.
 */
export interface IconPath {
  d: string;
  kind: 'stroke' | 'fill';
  /** stroke-linejoin round (most strokes only set round caps). */
  roundJoin?: boolean;
}

export interface IconDef {
  /** viewBox is `0 0 box box`. */
  box: number;
  paths: IconPath[];
}

