export type IconName = keyof typeof icons;

export const iconNames = Object.keys(icons) as IconName[];

/**
 * Stroke width in viewBox units so the line renders at 1.5px whatever size
 * the icon is drawn at.
 */
export function strokeWidthFor(def: IconDef, renderSize: number): number {
  return (1.5 * def.box) / renderSize;
}
